from scipy.optimize import least_squares
def run(f,n,tries=25,seed=0,inits=()):
    rng=np.random.default_rng(seed);best=None
    for i in range(tries):
        p0=rng.uniform(0.2,2,n)*rng.choice([1,1,-1],n)
        if i<len(inits): p0=np.array(inits[i],float)
        try:
            r=least_squares(lambda p:f(p)-sigma,p0,max_nfev=500)
            v=np.mean(r.fun**2)/sigma.var()
            if np.isfinite(v) and (best is None or v<best[0]): best=(v,r.x)
        except Exception as e: pass
    return best
